//
// File: SimulatorFrameTransportActor.swift
// Created by Vision Capture MVP
//

import Dispatch
import Foundation
import SimulatorFrameTransportContracts
import XPC

enum SimulatorFrameTransportError: Error, Equatable {
    case invalidState
    case invalidConfiguration
    case invalidMessage
    case transportFailure
}

struct SimulatorFrameTransportStartConfiguration: Equatable {
    let runID: String
    let selectedSimulatorUDID: String
    let deviceSet: SimulatorFrameStreamDeviceSetGroup
    let previewMode: SimulatorFrameStreamPreviewMode
    let maximumFPS: SimulatorFrameStreamMaximumFPS
    let fitPixelWidth: UInt64
    let fitPixelHeight: UInt64

    var isValid: Bool {
        SimulatorFrameDeviceSetIdentity.canonicalUUID(runID) != nil
            && SimulatorFrameDeviceSetIdentity.canonicalUUID(selectedSimulatorUDID) != nil
            && deviceSet.isValid
            && SimulatorFrameStreamScalarRule.areValidFitDimensions(
                mode: previewMode, width: fitPixelWidth, height: fitPixelHeight
            )
    }
}

enum SimulatorFrameTransportPhase: Equatable {
    case idle, connected, starting, streaming, updating, sourceReconfiguring, terminating, stopped, failed

    var isTerminal: Bool {
        self == .stopped || self == .failed
    }

    var isStreamLive: Bool {
        self == .streaming || self == .updating || self == .sourceReconfiguring
    }
}

/// The app-owned Gate 3 transport boundary. It never imports UI, Core, MCP, recording, or private
/// Simulator types. One event consumer serializes the authenticated XPC stream into this actor.
actor SimulatorFrameTransportActor {
    let session: XPCSession
    /// Immutable before XPC activation so activation diagnostics retain the canonical recording identity.
    let diagnosticRunID: String
    private let relay: SimulatorFrameTransportRelay
    let presentationMailbox: SimulatorFramePresentationMailbox?
    let surfaceOwner = SimulatorFrameTransportSurfaceOwner()

    var phase: SimulatorFrameTransportPhase = .idle
    var currentFrame: SimulatorFrameCurrentFrame?
    var receivedFrames: UInt64 = 0
    var rejectedFrames: UInt64 = 0
    var releasesSent: UInt64 = 0

    var startConfiguration: SimulatorFrameTransportStartConfiguration?
    var requestUUID = ""
    var runID = ""
    var selectedSimulatorUDID = ""
    var deviceSet: SimulatorFrameStreamDeviceSetGroup?
    var bootGeneration: UInt64 = 0
    var screenID: UInt64 = 0
    var screenUniqueID = ""
    var identityGeneration: UInt64 = 1
    var displayConfigurationGeneration: UInt64 = 0
    var configurationRevision: UInt64 = 0
    var streamGeneration: UInt64 = 1
    var latestFrameSequence: UInt64 = 0
    var lastReleasedFrameSequence: UInt64 = 0
    var appliedPreviewMode: SimulatorFrameStreamPreviewMode = .fitNotch
    var appliedMaximumFPS: SimulatorFrameStreamMaximumFPS = .thirty
    var outputPixelWidth: UInt64 = 0
    var outputPixelHeight: UInt64 = 0
    var pendingUpdate: SimulatorFrameTransportPendingUpdate?
    var postUpdateFrameExpectation: SimulatorFrameTransportPostUpdateFrameExpectation?
    var pendingUpdateContinuation: CheckedContinuation<
        SimulatorFrameTransportConfigurationUpdateOutcome,
        Never
    >?
    var sourceRequestToken: UInt64?
    var terminalCorrelationUUID: String?
    var startRejectionReason: SimulatorFrameStreamRejectedReason?
    var terminalFailureReason: SimulatorFrameStreamFailureReason?
    var terminalDiagnosticState = SimulatorFrameTransportTerminalDiagnosticState()

    private init(
        session: XPCSession,
        relay: SimulatorFrameTransportRelay,
        diagnosticRunID: String,
        presentationMailbox: SimulatorFramePresentationMailbox?
    ) {
        self.session = session
        self.relay = relay
        self.diagnosticRunID = diagnosticRunID
        self.presentationMailbox = presentationMailbox
    }

    static func connect(
        diagnosticRunID: String,
        presentationMailbox: SimulatorFramePresentationMailbox? = nil
    ) throws -> SimulatorFrameTransportActor {
        guard SimulatorFrameDeviceSetIdentity.canonicalUUID(diagnosticRunID) != nil else {
            throw SimulatorFrameTransportError.invalidConfiguration
        }
        let relay = SimulatorFrameTransportRelay()
        let helperRequirement = XPCPeerRequirement.isFromSameTeam(
            andMatchesSigningIdentifier: SimulatorFrameTransportContract.helperBundleIdentifier
        )
        let targetQueue = DispatchQueue(
            label: "com.hebert.VisionCapture.simulator-frame-transport",
            qos: .userInteractive
        )
        let session = try XPCSession(
            xpcService: SimulatorFrameTransportContract.helperBundleIdentifier,
            targetQueue: targetQueue,
            options: .inactive,
            requirement: helperRequirement,
            incomingMessageHandler: { dictionary in
                relay.yield(.message(dictionary))
                return nil
            },
            cancellationHandler: { _ in relay.yield(.invalidated) }
        )
        let transport = SimulatorFrameTransportActor(
            session: session,
            relay: relay,
            diagnosticRunID: diagnosticRunID,
            presentationMailbox: presentationMailbox
        )
        relay.consume(with: transport)
        return transport
    }

    func start(_ configuration: SimulatorFrameTransportStartConfiguration) throws {
        guard phase == .idle || phase == .connected,
              configuration.isValid,
              configuration.runID == diagnosticRunID
        else {
            throw SimulatorFrameTransportError.invalidConfiguration
        }
        let needsActivation = phase == .idle
        let requestUUID = UUID().uuidString.lowercased()
        self.requestUUID = requestUUID
        runID = configuration.runID
        selectedSimulatorUDID = configuration.selectedSimulatorUDID
        presentationMailbox?.begin(selectedSimulatorUDID: configuration.selectedSimulatorUDID)
        deviceSet = configuration.deviceSet
        startConfiguration = configuration
        appliedPreviewMode = configuration.previewMode
        appliedMaximumFPS = configuration.maximumFPS
        phase = .starting
        if needsActivation {
            do {
                try session.activate()
            } catch {
                failLocally(cause: .connectionActivationFailure, reason: "Simulator frame helper activation failed.")
                throw SimulatorFrameTransportError.transportFailure
            }
        }
        do {
            var builder = baseBuilder(.startStream, deviceSet: configuration.deviceSet)
            builder.put(SimulatorFrameTransportContract.expectedHelperBundleVersion,
                        "expectedHelperBundleVersion")
            builder.put(SimulatorFrameTransportContract.expectedMainAppBundleVersion,
                        "clientBundleVersion")
            builder.put(requestUUID, "requestUUID")
            builder.put(configuration.runID, "runID")
            builder.put(configuration.selectedSimulatorUDID, "selectedSimulatorUDID")
            builder.put(identityGeneration, "identityGeneration")
            builder.put(streamGeneration, "streamGeneration")
            builder.put(configuration.previewMode, "previewMode")
            builder.put(configuration.maximumFPS, "maximumFPS")
            builder.put(configuration.fitPixelWidth, "fitPixelWidth")
            builder.put(configuration.fitPixelHeight, "fitPixelHeight")
            try session.send(builder.message())
        } catch {
            failLocally(cause: .sendFailure, reason: "Simulator frame stream start failed.")
            throw SimulatorFrameTransportError.transportFailure
        }
    }

    func activate() throws {
        guard phase == .idle else { throw SimulatorFrameTransportError.invalidState }
        do {
            try session.activate()
            phase = .connected
        } catch {
            failLocally(cause: .connectionActivationFailure, reason: "Simulator frame helper activation failed.")
            throw SimulatorFrameTransportError.transportFailure
        }
    }

    func stop(disposition: SimulatorFrameStreamDisposition = .requestedStop) throws {
        guard phase == .streaming || phase == .updating || phase == .sourceReconfiguring else {
            throw SimulatorFrameTransportError.invalidState
        }
        guard let deviceSet else { throw SimulatorFrameTransportError.invalidState }
        presentationMailbox?.setState(.finalizing)
        let stopUUID = UUID().uuidString.lowercased()
        var builder = baseBuilder(.stopStream, deviceSet: deviceSet)
        builder.put(stopUUID, "requestUUID")
        putCurrentIdentity(into: &builder)
        builder.putClosedEnum(disposition, "disposition")
        do { try session.send(builder.message()) } catch { localTransportFailure() }
    }

    func receive(_ dictionary: XPCDictionary) {
        guard !phase.isTerminal else { return }
        do {
            let message = try SimulatorFrameStreamMessageReader(validating: dictionary)
            guard SimulatorFrameStreamKeys.direction(of: message.kind) == .helperToApp else {
                throw SimulatorFrameTransportError.invalidMessage
            }
            try handle(message)
        } catch {
            localProtocolFailure()
        }
    }

    func connectionInvalidated() {
        guard !phase.isTerminal else { return }
        recordTerminalCause(.connectionInvalidated)
        resolvePendingUpdate(.superseded)
        releaseCurrentIfNeeded(sendAcknowledgement: false)
        phase = .failed
        presentationMailbox?.setState(.unavailable, clearFrame: true)
    }

    // This closed nineteen-kind router has no data-dependent branching beyond the wire kind.
    // swiftlint:disable:next cyclomatic_complexity
    private func handle(_ message: SimulatorFrameStreamMessageReader) throws {
        switch message.kind {
        case .streamRejected: try handleRejected(message)
        case .streamStarted: try handleStarted(message)
        case .frame: try handleFrame(message)
        case .heartbeat: try handleHeartbeat(message)
        case .configurationReadyToSwitch: try handleConfigurationReady(message)
        case .configurationApplied: try handleConfigurationApplied(message)
        case .configurationRejected: try handleConfigurationRejected(message)
        case .sourceReconfiguring: try handleSourceReconfiguring(message)
        case .sourceReconfigured: try handleSourceReconfigured(message)
        case .streamTerminating: try handleTerminating(message)
        case .streamStopped, .streamFailed: try handleFinal(message)
        default: throw SimulatorFrameTransportError.invalidMessage
        }
    }

    func localProtocolFailure() {
        recordTerminalCause(.localProtocolFailure)
        rejectedFrames &+= 1
        resolvePendingUpdate(.superseded)
        releaseCurrentIfNeeded(sendAcknowledgement: false)
        phase = .failed
        presentationMailbox?.setState(.unavailable, clearFrame: true)
        session.cancel(reason: "Simulator frame stream protocol failure.")
    }

    func localTransportFailure() {
        failLocally(cause: .sendFailure, reason: "Simulator frame stream transport failure.")
    }

    func recordTerminalCause(_ cause: SimulatorFrameTransportTerminalCause) {
        _ = terminalDiagnosticState.recordObserved(cause)
    }

    func preRecordCleanupCause(_ cause: SimulatorFrameTransportTerminalCause) {
        _ = terminalDiagnosticState.preRecordCleanup(cause)
    }

    func hasRealChannelFailure() -> Bool {
        terminalDiagnosticState.cause?.isRealChannelFailure == true
    }

    func failLocally(cause: SimulatorFrameTransportTerminalCause, reason: String) {
        recordTerminalCause(cause)
        resolvePendingUpdate(.superseded)
        releaseCurrentIfNeeded(sendAcknowledgement: false)
        phase = .failed
        presentationMailbox?.setState(.unavailable, clearFrame: true)
        session.cancel(reason: reason)
    }
}

private enum SimulatorFrameTransportEvent: @unchecked Sendable {
    case message(XPCDictionary)
    case invalidated
}

private final class SimulatorFrameTransportRelay: @unchecked Sendable {
    private let stream: AsyncStream<SimulatorFrameTransportEvent>
    private let continuation: AsyncStream<SimulatorFrameTransportEvent>.Continuation

    init() {
        let pair = AsyncStream.makeStream(of: SimulatorFrameTransportEvent.self)
        stream = pair.stream
        continuation = pair.continuation
    }

    func yield(_ event: SimulatorFrameTransportEvent) {
        continuation.yield(event)
    }

    func consume(with actor: SimulatorFrameTransportActor) {
        Task {
            for await event in stream {
                switch event {
                case let .message(dictionary): await actor.receive(dictionary)
                case .invalidated:
                    await actor.connectionInvalidated()
                    continuation.finish()
                }
            }
        }
    }
}

//
// File: SimulatorFrameTransportAwaiting.swift
// Created by Vision Capture MVP
//

import Foundation
import SimulatorFrameTransportContracts

enum SimulatorFrameTransportWaitResult: Equatable {
    case ready
    case failed
    case timedOut
}

extension SimulatorFrameTransportActor {
    func waitForStreamingIdentity(
        until deadline: ContinuousClock.Instant,
        clock: ContinuousClock = ContinuousClock()
    ) async -> SimulatorFrameTransportWaitResult {
        while clock.now < deadline {
            if phase == .streaming { return .ready }
            if phase == .failed || phase == .stopped { return .failed }
            try? await Task.sleep(for: .milliseconds(10))
        }
        return .timedOut
    }

    func waitForFirstFrame(
        until deadline: ContinuousClock.Instant,
        clock: ContinuousClock = ContinuousClock()
    ) async -> SimulatorFrameTransportWaitResult {
        while clock.now < deadline {
            if phase == .streaming, latestFrameSequence > 0, currentFrame != nil {
                return .ready
            }
            if phase == .failed || phase == .stopped {
                return .failed
            }
            try? await Task.sleep(for: .milliseconds(10))
        }
        return .timedOut
    }

    func waitForTerminal(
        until deadline: ContinuousClock.Instant,
        clock: ContinuousClock = ContinuousClock()
    ) async -> SimulatorFrameTransportWaitResult {
        while clock.now < deadline {
            if phase == .stopped { return .ready }
            if phase == .failed { return .failed }
            try? await Task.sleep(for: .milliseconds(10))
        }
        return .timedOut
    }

    func waitForFailureOrTerminal() async -> SimulatorFrameTransportWaitResult {
        while true {
            if phase == .failed { return .failed }
            if phase == .stopped { return .ready }
            try? await Task.sleep(for: .milliseconds(50))
        }
    }

    func currentPhase() -> SimulatorFrameTransportPhase {
        phase
    }

    func failureSnapshot() -> (
        start: SimulatorFrameStreamRejectedReason?,
        terminal: SimulatorFrameStreamFailureReason?
    ) {
        (startRejectionReason, terminalFailureReason)
    }

    /// Emits one closed, privacy-safe terminal line once the runtime can include its writer state.
    func emitTerminalDiagnostic(writerConfirmed: Bool) {
        guard let diagnostic = terminalDiagnosticState.consume(
            runID: runID.isEmpty ? diagnosticRunID : runID,
            streamGeneration: streamGeneration,
            routeFingerprint: deviceSet.map { $0.kind.rawValue },
            phase: phase,
            receivedFirstFrame: receivedFrames > 0,
            writerConfirmed: writerConfirmed
        ) else { return }
        SimulatorFrameTransportTerminalDiagnostics.emit(diagnostic)
    }

    func appliedConfigurationSnapshot() -> SimulatorFrameTransportAppliedConfiguration? {
        guard phase == .streaming || phase == .updating || phase == .sourceReconfiguring else {
            return nil
        }
        return SimulatorFrameTransportAppliedConfiguration(
            previewMode: appliedPreviewMode,
            maximumFPS: appliedMaximumFPS,
            outputPixelWidth: outputPixelWidth,
            outputPixelHeight: outputPixelHeight
        )
    }

    func terminateLocally(cause: SimulatorFrameTransportTerminalCause) {
        guard !phase.isTerminal else { return }
        failLocally(cause: cause, reason: "Simulator frame stream ended during local cleanup.")
    }

    func terminateLocallyWithoutDiagnostic() {
        guard !phase.isTerminal else { return }
        resolvePendingUpdate(.superseded)
        releaseCurrentIfNeeded(sendAcknowledgement: false)
        phase = .failed
        presentationMailbox?.setState(.unavailable, clearFrame: true)
        session.cancel(reason: "Simulator frame stream channel failure cleanup.")
    }
}

//
// File: SimulatorFrameTransportActorMessages.swift
// Created by Vision Capture MVP
//

import Dispatch
import Foundation
import SimulatorFrameTransportContracts

extension SimulatorFrameTransportActor {
    func handleRejected(_ message: SimulatorFrameStreamMessageReader) throws {
        guard phase == .starting else { throw SimulatorFrameTransportError.invalidMessage }
        try requireSessionIdentity(message)
        let reason: SimulatorFrameStreamRejectedReason = try message.closedEnum(
            "reason", SimulatorFrameStreamRejectedReason.self
        )
        guard try message.string("helperBundleVersion")
            == SimulatorFrameTransportContract.expectedHelperBundleVersion,
            try message.canonicalUUID("requestUUID") == requestUUID,
            try message.positive("streamGeneration") == streamGeneration,
            try message.unsigned("activeRingSlotCount") == 0,
            try message.unsigned("stagingRingSlotCount") == 0
        else { throw SimulatorFrameTransportError.invalidMessage }
        startRejectionReason = reason
        recordTerminalCause(.helperFailure(.rejected(reason)))
        phase = .failed
        presentationMailbox?.setState(.unavailable, clearFrame: true)
        session.cancel(reason: "Simulator frame stream was rejected.")
    }

    func handleStarted(_ message: SimulatorFrameStreamMessageReader) throws {
        guard phase == .starting else { throw SimulatorFrameTransportError.invalidMessage }
        try requireSessionIdentity(message)
        let mode = try message.previewMode("appliedPreviewMode")
        let fps = try message.maximumFPS("appliedMaximumFPS")
        let width = try message.positive("outputPixelWidth")
        let height = try message.positive("outputPixelHeight")
        guard try message.string("helperBundleVersion")
            == SimulatorFrameTransportContract.expectedHelperBundleVersion,
            try message.string("acceptedClientBundleVersion")
            == SimulatorFrameTransportContract.expectedMainAppBundleVersion,
            try message.canonicalUUID("requestUUID") == requestUUID,
            try message.positive("streamGeneration") == streamGeneration,
            try message.positive("displayConfigurationGeneration") == 1,
            try message.positive("configurationRevision") == 1,
            try message.positive("bootGeneration") > 0,
            try message.positive("screenID") <= UInt64(UInt32.max),
            try !(message.string("screenUniqueID")).isEmpty,
            try message.unsigned("pixelFormat") == SimulatorFrameStreamContract.bgraPixelFormat,
            try message.unsigned("activeRingSlotCount")
            == SimulatorFrameStreamContract.activeRingSlotCount,
            try message.unsigned("stagingRingSlotCount") == 0,
            try message.unsigned("latestFrameSequence") == 0,
            isValidAppliedGeometry(mode: mode, width: width, height: height)
        else { throw SimulatorFrameTransportError.invalidMessage }
        bootGeneration = try message.positive("bootGeneration")
        screenID = try message.positive("screenID")
        screenUniqueID = try message.string("screenUniqueID")
        displayConfigurationGeneration = 1
        configurationRevision = 1
        appliedPreviewMode = mode
        appliedMaximumFPS = fps
        outputPixelWidth = width
        outputPixelHeight = height
        latestFrameSequence = 0
        phase = .streaming
        presentationMailbox?.setState(.starting)
    }

    func handleFrame(_ message: SimulatorFrameStreamMessageReader) throws {
        guard phase == .streaming else {
            // The helper can have already queued an old frame when a higher-priority transaction
            // fences delivery. It is refused before lookup and never changes app state.
            rejectedFrames &+= 1
            return
        }
        try requireCurrentIdentity(message)
        let sequence = try message.positive("frameSequence")
        let slotID = try message.unsigned("slotID")
        let leaseToken = try message.positive("leaseToken")
        let surfaceID = try message.positive("surfaceID")
        let pixelWidth = try message.positive("pixelWidth")
        let pixelHeight = try message.positive("pixelHeight")
        let bytesPerRow = try message.positive("bytesPerRow")
        guard try message.positive("bootGeneration") == bootGeneration,
              try message.positive("screenID") == screenID,
              try message.string("screenUniqueID") == screenUniqueID,
              sequence == SimulatorFrameStreamScalarRule.nextMonotonic(latestFrameSequence),
              SimulatorFrameStreamScalarRule.isValidSlotID(slotID),
              SimulatorFrameStreamScalarRule.isValidSurfaceID(surfaceID),
              try message.positive("sourceContinuousTimeNanoseconds") > 0,
              pixelWidth == outputPixelWidth,
              pixelHeight == outputPixelHeight,
              bytesPerRow >= pixelWidth * 4,
              try message.unsigned("pixelFormat") == SimulatorFrameStreamContract.bgraPixelFormat
        else { throw SimulatorFrameTransportError.invalidMessage }

        // The old owned surface and its exact lease acknowledgement leave first. Only then may a
        // public lookup create the newer owned mapping.
        releaseCurrentIfNeeded(sendAcknowledgement: true)
        let facts = SimulatorFrameTransportSurfaceOwner.ProvenFrame(
            runID: runID,
            streamGeneration: streamGeneration,
            displayConfigurationGeneration: displayConfigurationGeneration,
            configurationRevision: configurationRevision,
            frameSequence: sequence,
            slotID: slotID,
            leaseToken: leaseToken,
            surfaceID: surfaceID,
            pixelWidth: pixelWidth,
            pixelHeight: pixelHeight,
            bytesPerRow: bytesPerRow
        )
        let installed = try surfaceOwner.install(facts, from: message.surfaceObject("surface"))
        currentFrame = installed
        presentationMailbox?.publish(installed)
        latestFrameSequence = sequence
        receivedFrames &+= 1
        emitPostUpdateFrameIfExpected(
            sequence: sequence,
            pixelWidth: pixelWidth,
            pixelHeight: pixelHeight
        )
    }

    private func emitPostUpdateFrameIfExpected(
        sequence: UInt64,
        pixelWidth: UInt64,
        pixelHeight: UInt64
    ) {
        guard let expectation = postUpdateFrameExpectation,
              expectation.configurationRevision == configurationRevision,
              expectation.streamGeneration == streamGeneration
        else { return }
        SimulatorFrameTransportUpdateDiagnostics.postUpdateFrame(
            expectation,
            frameSequence: sequence,
            width: pixelWidth,
            height: pixelHeight,
            now: DispatchTime.now().uptimeNanoseconds
        )
        postUpdateFrameExpectation = nil
        resolvePendingUpdate(.applied(SimulatorFrameTransportAppliedConfiguration(
            previewMode: appliedPreviewMode,
            maximumFPS: appliedMaximumFPS,
            outputPixelWidth: outputPixelWidth,
            outputPixelHeight: outputPixelHeight
        )))
    }

    func handleHeartbeat(_ message: SimulatorFrameStreamMessageReader) throws {
        guard phase == .streaming else { throw SimulatorFrameTransportError.invalidMessage }
        try requireCurrentIdentity(message)
        guard try message.unsigned("latestFrameSequence") == latestFrameSequence,
              try message.previewMode("appliedPreviewMode") == appliedPreviewMode,
              try message.maximumFPS("appliedMaximumFPS") == appliedMaximumFPS,
              try message.unsigned("activeRingSlotCount")
              == SimulatorFrameStreamContract.activeRingSlotCount,
              try message.unsigned("stagingRingSlotCount") == 0
        else { throw SimulatorFrameTransportError.invalidMessage }
        _ = try message.unsigned("callbacksSeen")
        _ = try message.unsigned("callbacksAdmitted")
        _ = try message.unsigned("framesPublished")
        _ = try message.unsigned("framesDropped")
        if currentFrame != nil, pendingUpdate == nil {
            presentationMailbox?.setState(.staticHealthy)
        }
    }

    func isValidAppliedGeometry(
        mode: SimulatorFrameStreamPreviewMode,
        width: UInt64,
        height: UInt64
    ) -> Bool {
        guard width <= UInt64(UInt32.max), height <= UInt64(UInt32.max) else { return false }
        if mode == .fitNotch {
            guard let startConfiguration else { return false }
            return width == startConfiguration.fitPixelWidth
                && height == startConfiguration.fitPixelHeight
        }
        return true
    }
}

//
// File: LiveNotchPaintedCompositeRecorder.swift
// Created by Vision Capture MVP
//

import CoreGraphics
import CoreMedia
import Foundation
import IOSurface
import OSLog

private let notchCompositeRecorderLog = Logger(
    subsystem: "com.hebert.VisionCapture",
    category: "notchCompositeRecorder"
)

/// Produces the run's one video by PAINTING each frame from the device's real picture, instead of
/// screen-recording the notch window.
///
/// Owner decision, 2026-08-19: "I don't want two options. I want a single video, but it is
/// sharper... the new video that contain phone plus actions and more sharper." So this is a
/// producer swap, not an addition. It conforms to the same `LiveNotchRecording` protocol the
/// screen-capture recorder conforms to, is handed the same `run.workingVideoURL`, and therefore
/// flows through the identical finalization, validation, rename, state-marker and stop-response
/// path. A caller cannot tell which producer made the file, except that this one is sharp.
///
/// Why painting is sharper at all: the screen recorder captured the notch window, so its output
/// was capped by the display it was captured from — on a non-Retina monitor, one screen dot per
/// video dot. Painting reads the device's own full-resolution picture, which is already flowing
/// through the product, and never passes through the screen.
///
/// ## Why this runs on the main actor — do not "optimize" this onto a background queue
///
/// The app maps AT MOST ONE device surface at a time, and the transport releases the current
/// surface and acknowledges it BEFORE looking up a newer one
/// (`SimulatorFrameTransportSurface.swift`, `SimulatorFrameTransportSurfaceOwner`). A surface handed
/// out by the presentation mailbox can therefore have its ring slot returned to the helper — and
/// refilled with different pixels — while a slow reader is still looking at it.
///
/// So this recorder samples on the same beat, and on the same thread, as the on-screen tile, and
/// copies the pixels into its own buffer immediately. Copy first, encode later. Moving the sampling
/// off the main actor, or deferring the copy to "save main-thread time", reintroduces exactly that
/// race, and its symptom is not a crash: it is a proof video that quietly shows torn frames or
/// frames from the wrong stream generation. On a proof surface that is worse than recording
/// nothing.
@MainActor
final class LiveNotchPaintedCompositeRecorder: LiveNotchRecording {
    /// Same bounded wait the screen-capture recorder used for its writer to finish.
    private static let finishBudgetNanoseconds: UInt64 = 10_000_000_000

    /// How long `start` will wait for the presentation mailbox to carry a device frame.
    ///
    /// This wait is not optional and it is not defensive padding — see `awaitFirstDeviceFrame()`
    /// for the ordering hazard it closes. It is bounded well inside the run's own 30-second start
    /// deadline so a genuinely dead stream still fails the step rather than hanging it.
    private static let firstFrameWaitBudget: Duration = .seconds(10)

    private let mailbox: SimulatorFramePresentationMailbox
    private let model: ProofActivityHUDModel
    private let frameIntervalNanoseconds: UInt64

    private var painter: NotchCompositeFramePainter?
    private var writer: NotchCompositeVideoWriter?
    private var paintTask: Task<Void, Never>?
    private var startedAt: ContinuousClock.Instant?
    private var mailboxRevision: UInt64 = 0

    /// The newest device surface seen. Deliberately only ever replaced by a newer one, never
    /// cleared: when the stream stalls or goes unavailable the last good picture keeps being
    /// painted while the action feed carries on updating. That mirrors what the screen recorder
    /// produced during a stall — a frozen preview beside a live feed — so it changes no honesty
    /// property, and it keeps the video gapless. The feed is the truth channel; there is no
    /// synthetic "stalled" overlay, by owner ruling.
    private var lastDeviceSurface: IOSurfaceRef?

    private var feedImage: CGImage?
    private var feedRevision: NotchCompositeFeedRevision?

    init(
        mailbox: SimulatorFramePresentationMailbox,
        model: ProofActivityHUDModel,
        framesPerSecond: Int
    ) {
        self.mailbox = mailbox
        self.model = model
        frameIntervalNanoseconds = UInt64(1_000_000_000 / max(1, framesPerSecond))
    }

    func start(workingFileURL: URL) async -> LiveNotchRecorderStartResult {
        guard writer == nil else {
            return .failed(.recorderStartFailed("recorder_already_active"))
        }
        guard let frame = await awaitFirstDeviceFrame() else {
            return .failed(.recorderStartFailed("no_device_frame"))
        }
        let deviceSize = CGSize(
            width: Double(frame.pixelWidth),
            height: Double(frame.pixelHeight)
        )
        guard let layout = NotchCompositeLayout(devicePixelSize: deviceSize) else {
            return .failed(.recorderStartFailed("invalid_device_geometry"))
        }
        guard let painter = NotchCompositeFramePainter(layout: layout) else {
            return .failed(.recorderStartFailed("painter_unavailable"))
        }
        let created: NotchCompositeVideoWriter
        do {
            created = try NotchCompositeVideoWriter(
                outputURL: workingFileURL,
                pixelSize: layout.canvasPixelSize
            )
            try created.begin()
        } catch {
            return .failed(.recorderStartFailed(Self.reason(for: error)))
        }
        return await settleStart(painter: painter, writer: created, surface: frame.surface, layout: layout)
    }

    func stop() async -> LiveNotchRecorderStopResult {
        paintTask?.cancel()
        paintTask = nil
        guard let writer else { return .idle }
        self.writer = nil
        painter = nil
        startedAt = nil
        lastDeviceSurface = nil
        feedImage = nil
        feedRevision = nil
        let confirmed = await writer.finish(withinNanoseconds: Self.finishBudgetNanoseconds)
        let counts = writer.statistics()
        notchCompositeRecorderLog.info(
            """
            notchComposite stage=stop confirmed=\(confirmed, privacy: .public) \
            appended=\(counts.appended, privacy: .public) \
            dropped=\(counts.dropped, privacy: .public) \
            failures=\(counts.failures, privacy: .public)
            """
        )
        return confirmed ? .finalized : .stoppedWithoutFinishConfirmation
    }

    /// Writes the first frame before reporting started, so "started" keeps meaning what it meant
    /// under the previous recorder: the writer has genuinely begun writing, not merely opened.
    private func settleStart(
        painter: NotchCompositeFramePainter,
        writer: NotchCompositeVideoWriter,
        surface: IOSurfaceRef,
        layout: NotchCompositeLayout
    ) async -> LiveNotchRecorderStartResult {
        self.painter = painter
        self.writer = writer
        lastDeviceSurface = surface
        refreshFeedImageIfNeeded(layout: layout)
        guard let buffer = painter.paint(device: surface, feed: feedImage),
              writer.append(buffer, at: .zero)
        else {
            _ = await writer.finish(withinNanoseconds: Self.finishBudgetNanoseconds)
            self.writer = nil
            self.painter = nil
            lastDeviceSurface = nil
            return .failed(.recorderStartFailed("first_frame_not_written"))
        }
        startedAt = ContinuousClock.now
        notchCompositeRecorderLog.info(
            """
            notchComposite stage=start canvas=\
            \(Int(layout.canvasPixelSize.width), privacy: .public)x\
            \(Int(layout.canvasPixelSize.height), privacy: .public) device=\
            \(Int(layout.devicePixelSize.width), privacy: .public)x\
            \(Int(layout.devicePixelSize.height), privacy: .public)
            """
        )
        startPainting()
        return .started
    }

    private func startPainting() {
        paintTask = Task { @MainActor [weak self, frameIntervalNanoseconds] in
            while !Task.isCancelled {
                try? await Task.sleep(nanoseconds: frameIntervalNanoseconds)
                guard !Task.isCancelled, let self else { return }
                paintOneFrame()
            }
        }
    }

    private func paintOneFrame() {
        guard let painter, let writer, let startedAt else { return }
        if let frame = newestDeviceFrame() {
            lastDeviceSurface = frame.surface
        }
        refreshFeedImageIfNeeded(layout: painter.layout)
        guard let buffer = painter.paint(device: lastDeviceSurface, feed: feedImage) else { return }
        writer.append(buffer, at: Self.presentationTime(since: startedAt))
    }

    /// Waits, bounded, for the presentation mailbox to carry a device frame.
    ///
    /// ## Why this cannot be a single immediate read — regression 2026-08-19
    ///
    /// The run's `deliverFirstIdentityValidFrame` step guarantees the TRANSPORT has a frame: it
    /// returns as soon as `phase == .streaming`, `latestFrameSequence > 0` and the transport's own
    /// `currentFrame != nil` (`SimulatorFrameTransportAwaiting.swift:32-35`). It says nothing about
    /// the presentation mailbox, which is a separate hand-off.
    ///
    /// And the step immediately before it, `presentFixedNotchLayout`, calls
    /// `ProofActivityHUDPresenter.prepareSimulatorPreview`, which calls `mailbox.begin(...)`
    /// (`ProofActivityHUDPresenter.swift:162`) — and `begin` publishes state `.starting` with a nil
    /// frame, deliberately clearing whatever the mailbox held so the notch never opens on a
    /// previous run's picture.
    ///
    /// So the order is: mailbox cleared, then a wait that can be satisfied entirely by state the
    /// transport already had, then this recorder. When any frame had arrived before the notch was
    /// presented, that wait returns on its first loop iteration and the mailbox is still empty —
    /// and the only thing standing between the clear and the next `publish` is one frame interval.
    /// Reading once and refusing turned that into an instant `no_device_frame` and blocked
    /// recording outright.
    ///
    /// Waiting here removes the race rather than re-tuning it: the recorder asks for what it
    /// actually needs — a frame in the mailbox it samples from — instead of inferring it from a
    /// guarantee that was about something else.
    private func awaitFirstDeviceFrame() async -> SimulatorFrameCurrentFrame? {
        let deadline = ContinuousClock.now + Self.firstFrameWaitBudget
        var waited = false
        while ContinuousClock.now < deadline {
            if let frame = newestDeviceFrame() {
                if waited {
                    notchCompositeRecorderLog.info(
                        "notchComposite stage=firstFrame result=ready waited=true"
                    )
                }
                return frame
            }
            waited = true
            try? await Task.sleep(for: .milliseconds(10))
        }
        notchCompositeRecorderLog.error(
            "notchComposite stage=firstFrame result=timedOut budget=10s"
        )
        return nil
    }

    /// Drains the presentation mailbox. It does not consume — the cursor is per-reader — so the
    /// on-screen tile and this recorder read the same frames without starving each other.
    private func newestDeviceFrame() -> SimulatorFrameCurrentFrame? {
        guard let snapshot = mailbox.snapshot(after: mailboxRevision) else { return nil }
        mailboxRevision = snapshot.revision
        return snapshot.frame
    }

    /// Redraws the feed only when something it shows has changed, keeping a SwiftUI render off the
    /// per-frame path. A failed render leaves the previous image in place rather than blanking the
    /// column.
    private func refreshFeedImageIfNeeded(layout: NotchCompositeLayout) {
        let revision = NotchCompositeFeedRevision(model: model)
        guard revision != feedRevision || feedImage == nil else { return }
        feedRevision = revision
        if let rendered = NotchCompositeFeedImageRenderer.render(
            model: model,
            pointSize: layout.feedPointSize,
            scale: NotchCompositeLayout.feedRenderScale
        ) {
            feedImage = rendered
        }
    }

    private static func presentationTime(since start: ContinuousClock.Instant) -> CMTime {
        let elapsed = ContinuousClock.now - start
        let components = elapsed.components
        let nanoseconds = components.seconds * 1_000_000_000
            + components.attoseconds / 1_000_000_000
        return CMTime(value: max(0, nanoseconds), timescale: 1_000_000_000)
    }

    private static func reason(for error: Error) -> String {
        guard let failure = error as? NotchCompositeVideoWriterFailure else {
            return "writer_unavailable"
        }
        switch failure {
        case let .writerUnavailable(detail): return detail
        case let .startFailed(detail): return detail
        }
    }
}

