import AppKit
import QuartzCore
import SwiftUI

@MainActor
final class ProofActivityHUDPresenter {
    static let shared = ProofActivityHUDPresenter()

    private enum Constants {
        static let visibilityDefaultsKey = "proofActivityHUD.isVisible"
        static let collapsedDefaultsKey = "proofActivityHUD.isCollapsed"
        static let panelWidthDefaultsKey = "proofActivityHUD.panelWidth"
        /// Flush against the very top edge on ALL displays. Menu-bar overlap on
        /// non-notch displays is acceptable — the panel floats above.
        static let topInset: CGFloat = 0
        static let frameAnimationDuration: TimeInterval = 0.22
    }

    let model = ProofActivityHUDModel()
    let simulatorPreviewMailbox = SimulatorFramePresentationMailbox()

    private var panel: NSPanel?
    private var hostingController: NSHostingController<ProofActivityHUDView>?
    private var contentSizeObservation: NSKeyValueObservation?
    private var eventTask: Task<Void, Never>?
    private var clockTask: Task<Void, Never>?
    private var screenObserver: NSObjectProtocol?
    private(set) var isEnabled: Bool

    /// User-chosen panel width (via the footer −/+ buttons). When set it wins
    /// over the notch-derived width; nil means "auto-size to the notch".
    private var userWidth: CGFloat?

    /// True while the panel is put away — either by the × button or by going
    /// idle. It is deliberately NOT persisted and NOT the same as `isEnabled`:
    /// the next real event clears it, so the panel returns on its own.
    private var isDismissed = false
    private var preRunCollapsedState: Bool?
    var previewSettingsController: LiveTestPreviewRunSettingsController?

    private init() {
        let defaults = UserDefaults.standard
        if defaults.object(forKey: Constants.visibilityDefaultsKey) == nil {
            defaults.set(true, forKey: Constants.visibilityDefaultsKey)
        }
        isEnabled = defaults.bool(forKey: Constants.visibilityDefaultsKey)
        model.isCollapsed = defaults.bool(forKey: Constants.collapsedDefaultsKey)
        if defaults.object(forKey: Constants.panelWidthDefaultsKey) != nil {
            let stored = CGFloat(defaults.double(forKey: Constants.panelWidthDefaultsKey))
            userWidth = clampCardWidth(stored)
        }
    }

    func start() {
        guard eventTask == nil else { return }
        let panel = makePanel()
        self.panel = panel
        configureModelActions(panel: panel)
        layout(panel: panel)
        startEventTasks(panel: panel)
        observeScreenChanges()
    }

    private func configureModelActions(panel: NSPanel) {
        // Persist collapse choice and re-fit the panel when the strip is tapped.
        model.onCollapsedChanged = { [weak self] collapsed in
            guard let self else { return }
            UserDefaults.standard.set(collapsed, forKey: Constants.collapsedDefaultsKey)
            layout(panel: panel)
        }

        // Footer −/+ steps the panel width, clamped and persisted.
        model.onWidthStep = { [weak self] direction in
            guard let self else { return }
            let base = userWidth ?? model.preferredWidth
            let stepped = clampCardWidth(base + CGFloat(direction) * ProofActivityHUDMetrics.widthStep)
            userWidth = stepped
            UserDefaults.standard.set(Double(stepped), forKey: Constants.panelWidthDefaultsKey)
            layout(panel: panel)
        }

        // The × button puts the panel away without disabling the feature: the
        // next real event brings it straight back, so nothing has to be
        // re-enabled by hand.
        model.onDismiss = { [weak self] in
            guard let self else { return }
            isDismissed = true
            self.panel?.orderOut(nil)
        }
    }

    private func startEventTasks(panel: NSPanel) {
        eventTask = Task { [weak self] in
            for await event in ProofEventStream.subscribe() {
                guard let self else { return }
                let rendered = model.consume(event)
                if rendered, isEnabled {
                    // Any real event cancels a dismissal and ends idle-hiding.
                    isDismissed = false
                    layout(panel: panel)
                    panel.orderFrontRegardless()
                }
            }
        }
        clockTask = Task { [weak self] in
            while !Task.isCancelled {
                try? await Task.sleep(for: .seconds(1))
                guard !Task.isCancelled else { return }
                guard let self else { return }
                model.advanceClock()
                applyIdleAutoHide()
            }
        }
    }

    private func observeScreenChanges() {
        screenObserver = NotificationCenter.default.addObserver(
            forName: NSApplication.didChangeScreenParametersNotification,
            object: nil,
            queue: .main
        ) { [weak self] _ in
            Task { @MainActor in
                guard let self, let panel = self.panel else { return }
                self.layout(panel: panel)
            }
        }
    }

    func stop() {
        finishSimulatorPreview()
        eventTask?.cancel()
        eventTask = nil
        clockTask?.cancel()
        clockTask = nil
        contentSizeObservation?.invalidate()
        contentSizeObservation = nil
        if let screenObserver {
            NotificationCenter.default.removeObserver(screenObserver)
            self.screenObserver = nil
        }
        panel?.orderOut(nil)
        panel = nil
        hostingController = nil
    }
}

extension ProofActivityHUDPresenter {
    func prepareSimulatorPreview(
        selectedSimulatorUDID: String,
        runID: UUID? = nil
    ) -> SimulatorFramePresentationMailbox {
        if preRunCollapsedState == nil {
            preRunCollapsedState = model.isCollapsed
        }
        model.isCollapsed = false
        model.prepareSimulatorPreview(selectedSimulatorUDID: selectedSimulatorUDID, runID: runID)
        simulatorPreviewMailbox.begin(selectedSimulatorUDID: selectedSimulatorUDID)
        isDismissed = false
        if let panel {
            layout(panel: panel)
            panel.orderFrontRegardless()
        }
        return simulatorPreviewMailbox
    }

    /// Brings the panel forward for run activity the same way a real proof event brings it forward.
    /// It clears a dismissal but never overrides the user's own off switch.
    func surfaceForRunActivity() {
        isDismissed = false
        guard isEnabled, let panel else { return }
        layout(panel: panel)
        panel.orderFrontRegardless()
    }

    func finishSimulatorPreview() {
        if let previewSettingsController {
            Task { await previewSettingsController.transition(to: .terminal) }
        }
        previewSettingsController = nil
        simulatorPreviewMailbox.finish()
        model.finishSimulatorPreview()
        if let preRunCollapsedState {
            model.isCollapsed = preRunCollapsedState
            self.preRunCollapsedState = nil
        }
        if let panel {
            layout(panel: panel)
        }
    }

    func exactVisibleWindowID() -> CGWindowID? {
        guard let panel, panel.isVisible, panel.windowNumber > 0 else { return nil }
        let windowID = CGWindowID(panel.windowNumber)
        guard let rows = CGWindowListCopyWindowInfo([.optionIncludingWindow], windowID) as? [[String: Any]],
              let exact = ProofActivityHUDWindowIdentitySource.validatedExactWindowID(
                  windowNumber: panel.windowNumber,
                  processID: ProcessInfo.processInfo.processIdentifier,
                  rows: rows
              )
        else {
            return nil
        }
        return exact
    }

    func simulatorPreviewFitPixelSize() -> (width: UInt64, height: UInt64) {
        let scale = max(1, panel?.screen?.backingScaleFactor ?? NSScreen.main?.backingScaleFactor ?? 1)
        let width = UInt64((ProofActivityHUDMetrics.simulatorTileWidth * scale).rounded(.toNearestOrAwayFromZero))
        let height = UInt64((ProofActivityHUDMetrics.simulatorTileHeight * scale).rounded(.toNearestOrAwayFromZero))
        return (width + width % 2, height + height % 2)
    }

    func setEnabled(_ enabled: Bool) {
        guard !model.isSimulatorPreviewMounted else { return }
        isEnabled = enabled
        UserDefaults.standard.set(enabled, forKey: Constants.visibilityDefaultsKey)
        if enabled {
            guard let panel else { return }
            // Turning it back on from the menu also clears a dismissal, so the
            // menu item always does what it says.
            isDismissed = false
            layout(panel: panel)
            panel.orderFrontRegardless()
        } else {
            panel?.orderOut(nil)
        }
    }

    /// Puts the panel away once nothing has happened for the shared idle gap,
    /// so a finished run leaves the screen clean instead of parking a stale card
    /// there. Never fights the user: it only hides an already-visible panel and
    /// never re-shows one — that is the event handler's job.
    private func applyIdleAutoHide() {
        guard let panel, panel.isVisible, !isDismissed else { return }
        guard !model.isSimulatorPreviewMounted else { return }
        guard let lastEventAt = model.lastEventAt else { return }
        guard Date().timeIntervalSince(lastEventAt) >= ProofActivityHUDMetrics.idleAutoHideSeconds else { return }
        isDismissed = true
        panel.orderOut(nil)
    }

    func toggleEnabled() {
        setEnabled(!isEnabled)
    }

    private func makePanel() -> NSPanel {
        let panel = NSPanel(
            contentRect: CGRect(
                x: 0,
                y: 0,
                width: ProofActivityHUDMetrics.panelWidth(cardWidth: model.preferredWidth),
                height: 200
            ),
            styleMask: [.borderless, .nonactivatingPanel],
            backing: .buffered,
            defer: false
        )
        panel.backgroundColor = .clear
        panel.isOpaque = false
        // The card draws its own soft SwiftUI drop shadow into the transparent
        // margin, so the AppKit window shadow stays off.
        panel.hasShadow = false
        // Owner-amended click-through: the panel is interactive over the CARD
        // only. `HUDPassthroughView.hitTest` returns nil in the transparent
        // shadow margin so clicks there fall through to the app behind, while
        // the non-activating style keeps the panel from ever stealing focus.
        panel.ignoresMouseEvents = false
        panel.hidesOnDeactivate = false
        panel.becomesKeyOnlyIfNeeded = false
        panel.level = .statusBar
        panel.collectionBehavior = [.canJoinAllSpaces, .fullScreenAuxiliary, .transient]

        let hosting = NSHostingController(rootView: ProofActivityHUDView(
            model: model,
            simulatorPreviewMailbox: simulatorPreviewMailbox
        ))
        hosting.sizingOptions = [.preferredContentSize]
        hosting.view.wantsLayer = true
        hosting.view.layer?.backgroundColor = NSColor.clear.cgColor
        hostingController = hosting

        let container = HUDPassthroughView()
        // Only the concave shoulder crescents at the very top corners are
        // transparent now (the drop shadow is gone). They flare outward by the
        // shoulder radius, so treat that band as pass-through.
        container.horizontalMargin = ProofActivityHUDMetrics.shoulderRadius
        container.topMargin = ProofActivityHUDMetrics.shoulderRadius
        container.autoresizingMask = [.width, .height]
        hosting.view.translatesAutoresizingMaskIntoConstraints = false
        container.addSubview(hosting.view)
        NSLayoutConstraint.activate([
            hosting.view.leadingAnchor.constraint(equalTo: container.leadingAnchor),
            hosting.view.trailingAnchor.constraint(equalTo: container.trailingAnchor),
            hosting.view.topAnchor.constraint(equalTo: container.topAnchor),
            hosting.view.bottomAnchor.constraint(equalTo: container.bottomAnchor)
        ])
        panel.contentView = container

        // The SwiftUI card is content-driven; follow its fitting size so the
        // window frame always hugs the card as it collapses / expands / scrolls.
        contentSizeObservation = hosting.observe(\.preferredContentSize, options: [.new]) { [weak self] _, _ in
            Task { @MainActor in
                guard let self, let panel = self.panel else { return }
                self.layout(panel: panel)
            }
        }
        return panel
    }

    private func layout(panel: NSPanel) {
        guard let screen = preferredScreen() else { return }

        let hasNotchGeometry = screen.safeAreaInsets.top > 0
            && (screen.auxiliaryTopLeftArea != nil || screen.auxiliaryTopRightArea != nil)

        // A user width set via the footer −/+ wins; otherwise size the card
        // comfortably wider than the physical notch when we can measure it, else
        // the default width. Same panel and styling on every display.
        model.preferredWidth = userWidth ?? preferredCardWidth(for: screen, hasNotch: hasNotchGeometry)

        let width = ProofActivityHUDMetrics.panelWidth(cardWidth: model.preferredWidth)
        // Height is whatever the SwiftUI card currently fits into.
        let fitted = hostingController?.preferredContentSize.height ?? 0
        let height = fitted > 0 ? fitted : panel.frame.height

        let originX = screen.frame.midX - width / 2
        let originY = screen.frame.maxY - height - Constants.topInset
        let frame = CGRect(x: originX, y: originY, width: width, height: height)

        guard panel.frame != frame else { return }

        if panel.isVisible {
            NSAnimationContext.runAnimationGroup { context in
                context.duration = Constants.frameAnimationDuration
                context.timingFunction = CAMediaTimingFunction(name: .easeOut)
                panel.animator().setFrame(frame, display: true)
            }
        } else {
            panel.setFrame(frame, display: true)
        }
    }

    /// Notch width in points = screen width minus the two auxiliary areas that
    /// flank the camera housing. The card is sized to sit comfortably wider.
    private func preferredCardWidth(for screen: NSScreen, hasNotch: Bool) -> CGFloat {
        guard hasNotch,
              let leftArea = screen.auxiliaryTopLeftArea,
              let rightArea = screen.auxiliaryTopRightArea
        else {
            return ProofActivityHUDMetrics.defaultCardWidth
        }
        let notchWidth = screen.frame.width - leftArea.width - rightArea.width
        let target = notchWidth * 3.6
        return clampCardWidth(target)
    }

    private func clampCardWidth(_ width: CGFloat) -> CGFloat {
        min(ProofActivityHUDMetrics.maxCardWidth, max(ProofActivityHUDMetrics.minCardWidth, width))
    }

    private func preferredScreen() -> NSScreen? {
        NSScreen.screens.first(where: { $0.frame.contains(NSEvent.mouseLocation) })
            ?? NSScreen.main
            ?? NSScreen.screens.first
    }
}

/// Content view whose interactive area is the black body only. The panel now
/// hugs the shape, so the only transparent regions are the two concave shoulder
/// crescents at the top corners; clicks there return `nil` from `hitTest` and
/// fall through to whatever is behind the panel. Everything else — the
/// full-width top edge and the body — stays interactive.
private final class HUDPassthroughView: NSView {
    var horizontalMargin: CGFloat = 16
    var topMargin: CGFloat = 16

    override func hitTest(_ point: NSPoint) -> NSView? {
        let local = convert(point, from: superview)
        // Bottom-left origin: the shoulder crescents sit at the very top corners.
        let topBand = local.y >= bounds.maxY - topMargin
        let inLeftCorner = topBand && local.x <= horizontalMargin
        let inRightCorner = topBand && local.x >= bounds.maxX - horizontalMargin
        if inLeftCorner || inRightCorner { return nil }
        return super.hitTest(point)
    }
}

