import CaptureCore
import CoreGraphics
import Foundation
import OSLog
import SimulatorFrameTransportContracts

private let liveNotchRecordingRuntimeLog = Logger(
    subsystem: "com.hebert.VisionCapture",
    category: "liveNotchRecording"
)

extension LiveNotchRecordingProductionRuntime {
    /// Claims the run and takes ownership of the device prepared for it.
    ///
    /// Every path that does not claim the run releases that device's lease here, so a refused or
    /// invalid start can never leave a managed-set lease held for the life of the process.
    func beginTransaction(
        identity: RecordingV2LifecycleIdentity
    ) -> RecordingV2LifecycleStepOutcome {
        let prepared = preparedDevices.removeValue(forKey: identity.recordingID)
        if let failure = preparedFailures.removeValue(forKey: identity.recordingID) {
            prepared?.managedSet.release()
            return .failed(failure)
        }
        guard starting == nil, active == nil,
              let settings = preparedSettings.removeValue(forKey: identity.recordingID)
        else {
            prepared?.managedSet.release()
            return .failed(.previewSettingsInvalid)
        }
        do {
            _ = try LiveNotchRecordingFilesystem().validatedDestination(settings.destination)
        } catch {
            prepared?.managedSet.release()
            return .failed(.destinationUnavailable)
        }
        let resources = RunResources(identity: identity, settings: settings)
        resources.managedSet = prepared?.managedSet
        resources.resolvedUDID = prepared?.selectedUDID
        starting = resources
        return .passed
    }

    func validateHost() -> Bool {
        let system = NSDictionary(contentsOfFile: "/System/Library/CoreServices/SystemVersion.plist")
        let xcode = NSDictionary(contentsOfFile: "/Applications/Xcode.app/Contents/version.plist")
        let developerLink = try? FileManager.default.destinationOfSymbolicLink(
            atPath: "/var/db/xcode_select_link"
        )
        return system?["ProductVersion"] as? String == "26.5.2"
            && system?["ProductBuildVersion"] as? String == "25F84"
            && developerLink == "/Applications/Xcode.app/Contents/Developer"
            && xcode?["CFBundleShortVersionString"] as? String == "26.3"
            && xcode?["ProductBuildVersion"] as? String == "17C529"
    }

    func launchHelper(_ resources: RunResources) async -> RecordingV2LifecycleStepOutcome {
        let mailbox = await MainActor.run { ProofActivityHUDPresenter.shared.simulatorPreviewMailbox }
        let transport: SimulatorFrameTransportActor
        do {
            transport = try SimulatorFrameTransportActor.connect(
                diagnosticRunID: resources.identity.recordingID.uuidString.lowercased(),
                presentationMailbox: mailbox
            )
        } catch {
            SimulatorFrameTransportTerminalDiagnostics.emit(
                .connectionSetupFailure(runID: resources.identity.recordingID.uuidString.lowercased())
            )
            return .failed(.streamUnsupported)
        }
        resources.transport = transport
        do {
            try await transport.activate()
            guard !Task.isCancelled, owns(resources) else {
                await transport.preRecordCleanupCause(.localDeadlineExpired)
                await transport.terminateLocally(cause: .localDeadlineExpired)
                await transport.emitTerminalDiagnostic(writerConfirmed: false)
                return .failed(.startTimedOut)
            }
            return .passed
        } catch {
            await transport.emitTerminalDiagnostic(writerConfirmed: false)
            return .failed(.streamUnsupported)
        }
    }

    /// Publishes one real stage of this run's start order to the notch and the log.
    ///
    /// Called only from a code path that is about to do, or has just done, that exact work. There
    /// is no stage here that the product does not perform.
    func publishStage(
        _ stage: ProofActivityHUDRunStage,
        runID: UUID,
        deviceUDID: String,
        detail: String? = nil
    ) async {
        liveNotchRecordingRuntimeLog.info(
            "liveNotchRuntime stage=\(stage.rawValue, privacy: .public)"
        )
        await MainActor.run {
            ProofActivityHUDPresenter.shared.publishRunStage(
                stage,
                detail: detail,
                runID: runID,
                deviceUDID: deviceUDID
            )
        }
    }

    func publishStage(
        _ stage: ProofActivityHUDRunStage,
        resources: RunResources,
        detail: String? = nil
    ) async {
        await publishStage(
            stage,
            runID: resources.identity.recordingID,
            deviceUDID: resources.resolvedUDID ?? resources.identity.selectedUDID,
            detail: detail
        )
    }

    /// Binds the display of the device this run already resolved.
    ///
    /// The device set, the clone, and its power state were settled before the start budget opened.
    /// A run that somehow arrives here without them resolves them now rather than failing blind,
    /// which is the same work in the same order - only inside a budget that may not be long enough
    /// for a cold boot.
    func bindDeviceAndDisplay(_ resources: RunResources) async -> RecordingV2LifecycleStepOutcome {
        guard let transport = resources.transport else { return .failed(.streamUnsupported) }
        if resources.managedSet == nil || resources.resolvedUDID == nil {
            guard let prepared = await prepareManagedDevice(
                runID: resources.identity.recordingID,
                requestedUDID: resources.identity.selectedUDID
            ) else {
                return .failed(.deviceUnavailable)
            }
            resources.managedSet = prepared.managedSet
            resources.resolvedUDID = prepared.selectedUDID
        }
        guard let managedSet = resources.managedSet, let selectedUDID = resources.resolvedUDID else {
            return .failed(.deviceUnavailable)
        }
        await publishStage(
            .connectingDeviceDisplay,
            resources: resources,
            detail: cloneSubstitutionDetail(resources)
        )
        guard await startPreviewStream(
            resources,
            transport: transport,
            managedSet: managedSet,
            selectedUDID: selectedUDID
        ) else {
            return .failed(.previewStartFailed)
        }
        switch await transport.waitForStreamingIdentity(
            until: resources.identity.createdAt + .seconds(30)
        ) {
        case .ready:
            liveNotchRecordingRuntimeLog.info("liveNotchRuntime stage=streamingIdentity result=ready")
            return .passed
        case .timedOut:
            liveNotchRecordingRuntimeLog.info("liveNotchRuntime stage=streamingIdentity result=timedOut")
            return .failed(.startTimedOut)
        case .failed:
            await transport.emitTerminalDiagnostic(writerConfirmed: false)
            return .failed(await startFailure(for: transport))
        }
    }

    /// The preview configuration a RECORDED run streams with.
    ///
    /// Owner, 2026-08-19: "I want the preview of the streaming... of the simulator to be done with a
    /// high quality so that the recording of the notch have a better quality." The run's one video
    /// is painted from these frames, so Fit Notch — which shrinks the device's picture down to the
    /// on-screen tile before it ever reaches this process — would make every recording permanently
    /// soft no matter what the painter did. Native Device is therefore forced for the duration of a
    /// recorded run.
    ///
    /// The user's own choice is not altered: this rewrites only the in-memory configuration this
    /// run streams with. Nothing is written back to the stored setting, so the settings pane still
    /// shows what the user picked, a non-recorded preview still honours it, and it applies again
    /// unchanged the moment the run ends. The frame-rate half of the choice is carried through
    /// untouched.
    static func recordedRunPreviewConfiguration(
        _ configuration: LiveTestPreviewConfiguration
    ) -> LiveTestPreviewConfiguration {
        LiveTestPreviewConfiguration(size: .nativeDevice, maximumFPS: configuration.maximumFPS)
    }

    /// Snapshots the exact preview geometry this run freezes and opens the frame stream against the
    /// resolved managed-set device. Unchanged apart from taking the device the run resolved.
    private func startPreviewStream(
        _ resources: RunResources,
        transport: SimulatorFrameTransportActor,
        managedSet: LiveNotchManagedDeviceSetContext,
        selectedUDID: String
    ) async -> Bool {
        let size = await MainActor.run {
            ProofActivityHUDPresenter.shared.simulatorPreviewFitPixelSize()
        }
        resources.fitPixelWidth = size.width
        resources.fitPixelHeight = size.height
        let effective = Self.recordedRunPreviewConfiguration(resources.settings.previewConfiguration)
        resources.effectivePreviewConfiguration = effective
        let preview = SimulatorFrameTransportPreviewConfiguration(
            configuration: effective,
            fitPixelWidth: size.width,
            fitPixelHeight: size.height
        )
        resources.previewConfiguration = preview
        do {
            try await transport.start(SimulatorFrameTransportStartConfiguration(
                runID: resources.identity.recordingID.uuidString.lowercased(),
                selectedSimulatorUDID: selectedUDID,
                deviceSet: managedSet.group,
                previewMode: preview.previewMode,
                maximumFPS: preview.maximumFPS,
                fitPixelWidth: preview.fitPixelWidth,
                fitPixelHeight: preview.fitPixelHeight
            ))
        } catch {
            await transport.emitTerminalDiagnostic(writerConfirmed: false)
            return false
        }
        return true
    }

    func validateAppliedSettings(_ resources: RunResources) async -> RecordingV2LifecycleStepOutcome {
        guard let transport = resources.transport, let expected = resources.previewConfiguration,
              let applied = await transport.appliedConfigurationSnapshot(),
              applied.previewMode == expected.previewMode,
              applied.maximumFPS == expected.maximumFPS
        else {
            return .failed(.previewSettingsInvalid)
        }
        return .passed
    }

    func presentNotch(_ resources: RunResources) async -> RecordingV2LifecycleStepOutcome {
        guard let transport = resources.transport else { return .failed(.previewStartFailed) }
        let applied = resources.effectivePreviewConfiguration ?? resources.settings.previewConfiguration
        let controller = LiveTestPreviewRunSettingsController(
            initialConfiguration: applied
        ) { requested in
            await transport.applyPreviewConfiguration(
                requested,
                fitPixelWidth: resources.fitPixelWidth,
                fitPixelHeight: resources.fitPixelHeight
            )
        }
        resources.controls = controller
        await MainActor.run {
            let presenter = ProofActivityHUDPresenter.shared
            _ = presenter.prepareSimulatorPreview(
                selectedSimulatorUDID: resources.resolvedUDID ?? resources.identity.selectedUDID,
                runID: resources.identity.recordingID
            )
            presenter.configureSimulatorPreviewControls(
                controller: controller,
                initialConfiguration: applied
            )
        }
        resources.previewMounted = true
        return .passed
    }

    func waitForFirstFrame(_ resources: RunResources) async -> RecordingV2LifecycleStepOutcome {
        guard let transport = resources.transport else { return .failed(.previewStartFailed) }
        switch await transport.waitForFirstFrame(
            until: resources.identity.createdAt + .seconds(30)
        ) {
        case .ready:
            liveNotchRecordingRuntimeLog.info("liveNotchRuntime stage=firstFrame result=ready")
            return .passed
        case .timedOut:
            liveNotchRecordingRuntimeLog.info("liveNotchRuntime stage=firstFrame result=timedOut")
            return .failed(.startTimedOut)
        case .failed:
            await transport.emitTerminalDiagnostic(writerConfirmed: false)
            return .failed(.previewStartFailed)
        }
    }

    func freezeWindow(_ resources: RunResources) async -> RecordingV2LifecycleStepOutcome {
        let deadline = resources.identity.createdAt + .seconds(30)
        while ContinuousClock.now < deadline {
            guard !Task.isCancelled else {
                liveNotchRecordingRuntimeLog.info("liveNotchRuntime stage=exactWindow result=cancelled")
                return .failed(.startTimedOut)
            }
            if let windowID = await MainActor.run(body: {
                ProofActivityHUDPresenter.shared.exactVisibleWindowID()
            }) {
                guard !Task.isCancelled else {
                    liveNotchRecordingRuntimeLog.info("liveNotchRuntime stage=exactWindow result=cancelled")
                    return .failed(.startTimedOut)
                }
                guard ContinuousClock.now < deadline else {
                    liveNotchRecordingRuntimeLog.info("liveNotchRuntime stage=exactWindow result=timedOut")
                    return .failed(.startTimedOut)
                }
                resources.exactWindowID = windowID
                liveNotchRecordingRuntimeLog.info("liveNotchRuntime stage=exactWindow result=ready")
                return .passed
            }
            do {
                try await Task.sleep(for: .milliseconds(25))
            } catch {
                liveNotchRecordingRuntimeLog.info("liveNotchRuntime stage=exactWindow result=cancelled")
                return .failed(.startTimedOut)
            }
        }
        liveNotchRecordingRuntimeLog.info("liveNotchRuntime stage=exactWindow result=timedOut")
        return .failed(.startTimedOut)
    }

    func startRecorder(_ resources: RunResources) async -> RecordingV2LifecycleStepOutcome {
        // The exact-window stage still runs and still has to have succeeded. The painted producer
        // does not film that window, but the stage sequence is part of the run's recorded shape and
        // is deliberately left exactly as it was.
        guard let windowID = resources.exactWindowID else { return .failed(.recorderStartFailed) }
        liveNotchRecordingRuntimeLog.info("liveNotchRuntime stage=recorderPrepareRunEntered")
        let phaseDeadline = resources.identity.createdAt + .seconds(30)
        let session = LiveNotchRecordingSession(
            recorder: await makeVideoProducer(resources, windowID: windowID),
            makeRecordingID: { resources.identity.recordingID }
        )
        resources.recordingSession = session
        switch await session.start(
            destination: resources.settings.destination,
            selectedUDID: resources.resolvedUDID ?? resources.identity.selectedUDID
        ) {
        case let .recording(run):
            liveNotchRecordingRuntimeLog.info("liveNotchRuntime stage=writerStartConfirmed")
            guard !Task.isCancelled, owns(resources) else {
                _ = await session.finalizeRecorder()
                return .failed(.startTimedOut)
            }
            resources.run = run
            return .passed
        case .failed:
            if ContinuousClock.now >= phaseDeadline { return .failed(.startTimedOut) }
            return .failed(.recorderStartFailed)
        }
    }

    func startFailure(
        for transport: SimulatorFrameTransportActor
    ) async -> RecordingV2LifecycleStartFailure {
        let reason = await transport.failureSnapshot().start
        return switch reason {
        case .deviceUnavailable: .deviceUnavailable
        case .displayUnavailable: .displayUnavailable
        case .unsupportedCompatibilityOrABI, .protocolMismatch, .bundleVersionMismatch:
            .streamUnsupported
        case .invalidConfiguration: .previewSettingsInvalid
        default: .previewStartFailed
        }
    }

    func nanoseconds(until deadline: ContinuousClock.Instant) -> UInt64 {
        let components = ContinuousClock.now.duration(to: deadline).components
        guard components.seconds >= 0 else { return 0 }
        let seconds = UInt64(components.seconds)
        let attoseconds = UInt64(max(0, components.attoseconds))
        let (whole, overflow) = seconds.multipliedReportingOverflow(by: 1_000_000_000)
        guard !overflow else { return .max }
        return whole.addingReportingOverflow(attoseconds / 1_000_000_000).partialValue
    }
}

