#import "SimulatorFramePrivateAdapterInternal.h"
#import "SimulatorFramePrivateStreamInternal.h"
#import "SimulatorFramePrivateStreamStateInternal.h"

@implementation VCSimulatorFramePrivateStream (Admission)

- (void)handleFrameCallbackForToken:(uint64_t)generationToken {
    self.callbacksSeen += 1;
    [self admitCurrentDescriptorSurfaceForToken:generationToken
                                admissionOrigin:VCFrameAdmissionOriginFrameCallback];
}

- (void)admitInitialSurfaceSnapshotForToken:(uint64_t)generationToken {
    [self admitCurrentDescriptorSurfaceForToken:generationToken
                                admissionOrigin:VCFrameAdmissionOriginInitialSurfaceSnapshot];
}

- (BOOL)admitCommittedConfigurationSurfaceForToken:(uint64_t)generationToken {
    return [self admitCurrentDescriptorSurfaceForToken:generationToken
                                       admissionOrigin:VCFrameAdmissionOriginCommittedConfiguration];
}

- (BOOL)admitCurrentDescriptorSurfaceForToken:(uint64_t)generationToken
                             admissionOrigin:(VCFrameAdmissionOrigin)admissionOrigin {
    // Late callbacks from a retired generation are fenced here and do nothing else.
    if (self.terminal || self.admissionFenced || generationToken != self.sourceConfigurationToken) {
        return NO;
    }
    uint64_t now = VCFrameContinuousNanoseconds();
    if (self.admittedFirstCallback) {
        uint64_t interval = self.configuration.admissionIntervalNanoseconds;
        if (interval == 0 || (now - self.lastAdmittedNanoseconds) < interval) {
            self.droppedByFPS += 1;
            return NO;
        }
    }
    // Never copy the callback payload. The accepted initial snapshot already proved the callback
    // surface and one descriptor getter match the baseline; this is a fresh getter on that same
    // accepted descriptor and then the normal validation/copy path.
    id surfaceObject = [(id<VCSimDisplayIOSurfaceRenderableCalling>)self.displayDescriptor framebufferSurface];
    if (admissionOrigin != VCFrameAdmissionOriginFrameCallback &&
        !VCFrameSurfaceMatchesBaseline(surfaceObject, self.sourceCallbackBaseline)) {
        [self handleSourceChangeForToken:generationToken reason:VCFrameSourceChangeSurfaces];
        return NO;
    }
    if (surfaceObject == nil) {
        VCFrameLogRawSurfaceUnavailable();
        [self failOnStateQueueWithReason:VCSimulatorFramePrivateStreamFailureRawSurfaceUnavailable];
        return NO;
    }
    CFTypeRef rawType = (__bridge CFTypeRef)surfaceObject;
    if (CFGetTypeID(rawType) != IOSurfaceGetTypeID()) {
        VCFrameLogRawSurfaceTypeInvalid(CFGetTypeID(rawType), IOSurfaceGetTypeID());
        [self failOnStateQueueWithReason:VCSimulatorFramePrivateStreamFailureRawSurfaceInvalid];
        return NO;
    }
    VCFrameSurfaceLayout layout;
    if (!VCFrameReadSurfaceLayout((IOSurfaceRef)rawType, &layout)) {
        VCFrameLogRawSurfaceLayoutInvalid((IOSurfaceRef)rawType);
        [self failOnStateQueueWithReason:VCSimulatorFramePrivateStreamFailureRawSurfaceInvalid];
        return NO;
    }
    if (layout.width != self.nativePixelWidth || layout.height != self.nativePixelHeight) {
        VCFrameLogRawSurfaceDimensionChanged(
            layout.width, layout.height, self.nativePixelWidth, self.nativePixelHeight
        );
        [self failOnStateQueueWithReason:VCSimulatorFramePrivateStreamFailureDisplayIdentityChanged];
        return NO;
    }
    self.admittedFirstCallback = YES;
    self.lastAdmittedNanoseconds = now;
    self.callbacksAdmitted += 1;
    if (admissionOrigin == VCFrameAdmissionOriginInitialSurfaceSnapshot) {
        VCFrameLogInitialSurfaceSnapshotAdmission();
    }
    uint64_t callbackOrdinal = self.callbackOrdinal;
    if (!VCFrameIncrementMonotonic(&callbackOrdinal)) {
        [self failOnStateQueueWithReason:VCSimulatorFramePrivateStreamFailureMonotonicValueOverflow];
        return NO;
    }
    self.callbackOrdinal = callbackOrdinal;
    IOSurfaceRef raw = (IOSurfaceRef)CFRetain(rawType);
    if (self.copyInFlight) {
        // At most one replaceable newest raw candidate waits behind the one serial copy.
        if (self.pendingRawCandidate != NULL) {
            CFRelease(self.pendingRawCandidate);
            self.droppedSupersededCandidate += 1;
        }
        self.pendingRawCandidate = raw;
        self.pendingCallbackOrdinal = self.callbackOrdinal;
        self.pendingCandidateNanoseconds = now;
        return YES;
    }
    [self submitCopyOnStateQueueForRaw:raw ordinal:self.callbackOrdinal capturedAt:now];
    return !self.terminal && (self.copyInFlight || self.pendingRawCandidate != NULL);
}

@end

