import Foundation
import Synchronization

enum SimulatorFramePreviewState: String, CaseIterable {
    case inactive
    case starting
    case live
    case updating
    case updateFailed
    case staticHealthy
    case unavailable
    case finalizing

    var visibleLabel: String {
        switch self {
        case .inactive: "PREVIEW OFF"
        case .starting: "STARTING"
        case .live: "LIVE"
        case .updating: "UPDATING"
        case .updateFailed: "UPDATE FAILED"
        case .staticHealthy: "LIVE · STATIC"
        case .unavailable: "STREAM UNAVAILABLE"
        case .finalizing: "FINALIZING"
        }
    }
}

struct SimulatorFramePresentationSnapshot: @unchecked Sendable {
    let revision: UInt64
    let selectedSimulatorUDID: String
    let state: SimulatorFramePreviewState
    let frame: SimulatorFrameCurrentFrame?
}

/// A one-value presentation seam between the frame transport actor and the display-linked UI.
/// It keeps only the newest state and surface. The UI drains it synchronously on display refresh.
final class SimulatorFramePresentationMailbox: Sendable {
    private struct Storage {
        var revision: UInt64 = 0
        var selectedSimulatorUDID = ""
        var state: SimulatorFramePreviewState = .inactive
        var frame: SimulatorFrameCurrentFrame?
    }

    private let storage = Mutex(Storage())

    func begin(selectedSimulatorUDID: String) {
        update(selectedSimulatorUDID: selectedSimulatorUDID, state: .starting, frame: nil)
    }

    func publish(_ frame: SimulatorFrameCurrentFrame) {
        update(selectedSimulatorUDID: nil, state: .live, frame: frame)
    }

    func setState(_ state: SimulatorFramePreviewState, clearFrame: Bool = false) {
        storage.withLock { value in
            value.revision &+= 1
            value.state = state
            if clearFrame {
                value.frame = nil
            }
        }
    }

    func finish() {
        update(selectedSimulatorUDID: "", state: .inactive, frame: nil)
    }

    func snapshot(after revision: UInt64) -> SimulatorFramePresentationSnapshot? {
        storage.withLock { value in
            guard value.revision != revision else { return nil }
            return SimulatorFramePresentationSnapshot(
                revision: value.revision,
                selectedSimulatorUDID: value.selectedSimulatorUDID,
                state: value.state,
                frame: value.frame
            )
        }
    }

    private func update(
        selectedSimulatorUDID: String?,
        state: SimulatorFramePreviewState,
        frame: SimulatorFrameCurrentFrame?
    ) {
        storage.withLock { value in
            value.revision &+= 1
            if let selectedSimulatorUDID {
                value.selectedSimulatorUDID = selectedSimulatorUDID
            }
            value.state = state
            value.frame = frame
        }
    }
}
